// Focused data and migration tests, using only fresh in-memory instances.
if(UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode || UnityEditor.EditorApplication.isCompiling)throw new System.Exception("Idle Edit Mode required");
var checks=new System.Collections.Generic.List<string>();
System.Action<bool,string> check=(condition,label)=>{if(!condition)throw new System.Exception(label);checks.Add(label);};
System.Action<System.Action,string> rejects=(action,label)=>{try{action();}catch(System.Exception){checks.Add(label);return;}throw new System.Exception(label);};
var data=new ProjectY.Data.PartyStoryData();
var a=new ProjectY.Data.CombatActorData(1,1);var b=new ProjectY.Data.CombatActorData(2,2);var c=new ProjectY.Data.CombatActorData(3,3);
foreach(var actor in new[]{a,b,c}){actor.SetMaxHP(100);actor.Restore();actor.Deploy(1,actor.Id,0);}
data.BeginBattle();foreach(var actor in new[]{a,b,c})data.AddParticipant(actor);
check(ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"heal",3,0,2),"first treatment");
check(ProjectY.Data.PartyRelationshipState.Interact(data,2,1,"heal",2,0,2),"reciprocal shared cap");
check(!ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"heal",1,0,2) && data.Score(1,2)==5,"treatment cap");
check(ProjectY.Data.PartyRelationshipState.AttackPartners(data,1,20,1).Length==0,"first attack is not cooperation");
check(ProjectY.Data.PartyRelationshipState.AttackPartners(data,2,20,1).SequenceEqual(new[]{1}),"same-round partner");
check(ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"cooperate",3,0,2),"cooperation reward");
ProjectY.Data.PartyRelationshipState.AttackPartners(data,1,21,1);ProjectY.Data.PartyRelationshipState.AttackPartners(data,2,21,1);
check(!ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"cooperate",3,0,2),"multiple targets cannot bypass per-round cap");
check(ProjectY.Data.PartyRelationshipState.AttackPartners(data,2,20,2).Length==0,"new round clears attackers");
ProjectY.Data.PartyRelationshipState.AttackPartners(data,1,20,2);
check(ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"cooperate",3,0,2),"next round cooperation");
check(ProjectY.Data.PartyRelationshipState.Interact(data,1,2,"harm",-18,9,1000000),"friendly damage reduces score");
check(!data.TryRescue(2,1,20) && !ProjectY.Data.PartyRelationshipState.Interact(data,2,1,"heal",3,0,2),"friendly damage prevents pair farming");
ProjectY.Data.PartyRelationshipState.AddFriendlyDamage(data,2,20);
check(ProjectY.Data.PartyRelationshipState.CreditHealing(data,2,10)==0 && ProjectY.Data.PartyRelationshipState.FriendlyDebt(data,2)==10,"healing pays friendly injury first");
check(ProjectY.Data.PartyRelationshipState.CreditHealing(data,2,15)==5,"only enemy-injury remainder grants credit");
int before=data.Score(1,2);check(data.SettleBattle(true,2) && data.Score(1,2)==before,"victory does not erase friendly fire");
check(!data.SettleBattle(true,2),"settlement idempotence");
check(ProjectY.Data.PartyRelationshipState.Social(data,1,2,1,2,-8),"apology repairs grievance");
check(!ProjectY.Data.PartyRelationshipState.Social(data,2,1,1,3,0),"daily interaction cap is reciprocal");
ProjectY.Data.PartyRelationshipState.SetRomance(data,1,2,true);
rejects(()=>ProjectY.Data.PartyRelationshipState.SetRomance(data,1,3,true),"overlapping romance rejected");
var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
var capture=typeof(ProjectY.Data.PartyStoryData).GetMethod("Capture",flags);
var prepare=typeof(ProjectY.Data.PartyStoryData).GetMethod("Prepare",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);
var saved=capture.Invoke(data,null);
var ids=new System.Collections.Generic.HashSet<int>(new[]{1,2,3});
System.Func<object,bool,ProjectY.Data.PartyStoryData> load=(payload,legacy)=>(ProjectY.Data.PartyStoryData)prepare.Invoke(null,new object[]{payload,ids,legacy,1440d});
var restored=load(saved,false);
check(restored.Score(1,2)==data.Score(1,2) && ProjectY.Data.PartyRelationshipState.Romance(restored,1,2),"negative score and romance roundtrip");
check(ProjectY.Data.PartyRelationshipState.Grievance(restored,1,2)==1 && ProjectY.Data.PartyRelationshipState.SocialDay(restored,1,2)==1,"grievance and daily cap roundtrip");
check(restored.ParticipantCount==0 && ProjectY.Data.PartyRelationshipState.FriendlyDebt(restored,2)==0,"battle receipts are transient");
var bonds=(System.Array)saved.GetType().GetField("bonds").GetValue(saved);var first=bonds.GetValue(0);var rowType=first.GetType();
rowType.GetField("socialDay").SetValue(first,100);rejects(()=>load(saved,false),"future conversation date rejected");
rowType.GetField("socialDay").SetValue(first,1);rowType.GetField("score").SetValue(first,60);
var legacyData=load(saved,true);
check(legacyData.Score(1,2)==60 && !ProjectY.Data.PartyRelationshipState.Romance(legacyData,1,2) && ProjectY.Data.PartyRelationshipState.SocialDay(legacyData,1,2)==0,"legacy scores preserved without invented relationships");
saved.GetType().GetField("format").SetValue(saved,0);rejects(()=>load(saved,false),"current saves require relationship format");
return new {passed=checks.Count,checks=checks};
